sub links 
{
  my ($self, $links) = @_;

  if (ref $links eq 'HASH') {
    my $raw = join ' ', map {
      my ($name, $href) = @$_;
      my @rels = ('rel' => $name);
      push @rels, 'title' => $href->{title} if $href->{title};
      join '; ', map {
        my ($k, $v) = @$_;
        $v ? qq{$k="$v"} : $k;
      } @rels;
      qq{<$href>; $rels};
    } [sort keys %$links], map { @$_ } values %$links;
    $self->link($raw);
    $self;
  } else {
    my $value = $self->link;
    return unless defined $value;
    my @links = map { s/^\s*<([^>]+)>(?:\s*;\s*(.*))?\s*$/$1,$2/; $_ } split /\s*[;,]\s*/, $value;
    my %result;
    for my $link (@links) {
      next unless defined $link && $link =~ m/^([^,]+),(.*)$/;
      my ($href, $rest) = ($1, $2);
      $href =~ s/^\s*<([^>]+)>\s*$/$1/;
      my @rels;
      if ($rest =~ m/^rel\s*=\s*"([^"]*)"/) {
        push @rels, $1;
        $rest =~ s/^rel\s*=\s*"[^"]*"\s*;;?\s*//;
      } elsif ($rest =~ m/^rel=([^;]+);?/) {
        push @rels, $1;
        $rest =~ s/^rel=[^;]*;?//;
      }
      $rest =~ s/;?\s*(title\s*=\s*"([^"]*)")//;
      push @result{$href}->{'rel'}, @rels if @rels;
      push @result{$href}->{'title'}, $2 if defined $2;
    }
    %result;
  }
}
