sub build_app {
  my ($self, $app, @args) = @_;

  my $log = shift @args;

  # Handle hashref style arguments
  if (ref $log eq 'HASH') {
    %args = %$log;
    $log = $args{log};
  }

  # Handle named arguments (e.g., log => Mojo::Log->new)
  if (@args) {
    if (ref $args[0] eq 'HASH') {
      %args = %{$args[0]};
    } else {
      # If we have arguments but they are not a hash, treat first arg as the app class
      # and shift the rest to @args
      my $class = $app;
      $app = shift @args if @args;
      %args = @args ? (map { my ($k, $v) = @$_; $k => $v } @args) : ();
    }
  }

  my $class = $app;
  $class //= 'Mojo::HelloWorld';

  # Load the class
  $class = Mojo::Loader::load_class($class) or return;

  # Instantiate the application
  my $app_instance = $class->new(@args);

  # Assign to the server's app attribute
  $self->app($app_instance);

  return $app_instance;
}

