use Mojo::Base 'Mojo::Server';
use Mojo::IOLoop;
use Mojo::Transaction::WebSocket;
use Mojo::URL;
use Mojo::Util      qw(term_escape);
use Mojo::WebSocket qw(server_handshake);
use Carp qw(croak);
use Scalar::Util    qw(weaken);
sub start {
my $self = shift;
[MASK]
