# File: mojo/lib/Mojo/Exception.pm
sub to_string {
  my $self = shift;

  my $str = $self->message;

  my $frames = $self->frames;
  if ($str !~ /\n$/) {
    $str .= @$frames ? " at $frames->[0][1] line $frames->[0][2].\n" : "\n";
  }
  return $str unless $self->verbose;

  my $line = $self->line;
  if (@$line) {
    $str .= "Context:\n";
    $str .= "  $_->[0]: $_->[1]\n" for @{$self->lines_before};
    $str .= "  $line->[0]: $line->[1]\n";
    $str .= "  $_->[0]: $_->[1]\n" for @{$self->lines_after};
  }

  if (my $max = @$frames) {
    $str .= "Traceback (most recent call first):\n";
    $str .= qq{  File "$_->[1]", line $_->[2], in "$_->[3]"\n} for @$frames;
  }

  return $str;
}
# File: mojo/lib/Mojo/UserAgent/CookieJar.pm
sub to_string {
  my $self = shift;

  my @lines;
  for my $cookie (@{$self->all}) {
    my $line = [
      $cookie->domain, $cookie->host_only ? 'FALSE' : 'TRUE',
      $cookie->path,   $cookie->secure    ? 'TRUE'  : 'FALSE',
      $cookie->expires // 0, $cookie->name,
      $cookie->value
    ];
    push @lines, join "\t", @$line;
  }

  return join "\n", @lines, '';
}
