  Server: Mojolicious (Perl)

  1
  H
  3
  ell
  2
  o!
  0

=head2 write_sse

  $c = $c->write_sse;
  $c = $c->write_sse($event);
  $c = $c->write_sse($event => sub ($c) {...});

